SELECT ?g (COUNT(*) AS ?triples)
WHERE {
  GRAPH ?g {
    ?s ?p ?o
  }
}
GROUP BY ?g
ORDER BY DESC(?triples)

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

CONSTRUCT {
  ?scheme a skos:ConceptScheme ;
    skos:prefLabel ?label ;
    skos:notation ?notation ;
    dct:publisher ?publisher ;
    dct:subject ?subject ;
    dct:license ?license .
  ?subject skos:prefLabel ?subjectLabel ;
    skos:notation ?subjectNotation .
}
WHERE {
  GRAPH <https://bartoc.org/graph/terminology/> {
    BIND(<http://bartoc.org/en/node/18785> AS ?scheme)
    ?scheme a skos:ConceptScheme .
    OPTIONAL { ?scheme skos:prefLabel ?label . FILTER (LANG(?label) = "en") }
    OPTIONAL { ?scheme skos:notation ?notation }
    OPTIONAL { ?scheme dct:publisher ?publisher }
    OPTIONAL { ?scheme dct:license ?license }
    OPTIONAL {
      ?scheme dct:subject ?subject .
      OPTIONAL { ?subject skos:prefLabel ?subjectLabel . FILTER (LANG(?subjectLabel) = "en") }
      OPTIONAL { ?subject skos:notation ?subjectNotation }
    }
  }
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

CONSTRUCT {
  ?terminology dct:subject ?subject ;
    skos:prefLabel ?terminologyLabel .
  ?subject a skos:Concept ;
    skos:prefLabel ?subjectLabel ;
    skos:notation ?notation ;
    skos:inScheme ?scheme .
  ?scheme skos:prefLabel ?schemeLabel .
}
WHERE {
  GRAPH <https://bartoc.org/graph/terminology/> {
    BIND(<http://uri.gbv.de/terminology/bk/74.07> AS ?subject)
    ?terminology dct:subject ?subject ;
      skos:prefLabel ?terminologyLabel .
    FILTER (LANG(?terminologyLabel) = "en")
    ?subject a skos:Concept ;
      skos:prefLabel ?subjectLabel ;
      skos:notation ?notation ;
      skos:inScheme ?scheme .
    FILTER (LANG(?subjectLabel) = "en")
    ?scheme skos:prefLabel ?schemeLabel .
    FILTER (LANG(?schemeLabel) = "en")
  }
}

SELECT ?class (COUNT(?instance) AS ?count)
WHERE {
  ?instance a ?class
}
GROUP BY ?class
ORDER BY DESC(?count)

SELECT ?property (COUNT(*) AS ?count)
WHERE {
  ?subject ?property ?object
}
GROUP BY ?property
ORDER BY DESC(?count)
